//! 🧊️ Full typed BRep topology, analytic geometry, p-curves and NURBS parameter sequences.
use crate::standards::v1::subsets::base::schema::snapshot::sqlite::native::Bound;
use semio_framework_os_kernel::sqlite_snapshot::artifact::{FloatColumn,FloatRow as SqliteRow,insert_ieee754,insert_key_ieee754};
use super::{SemioBrepSnapshot,BrepVertex,BrepEdge,BrepLoop,BrepLoopEdge,BrepCoedge,BrepFace,BrepShell,BrepShellFace,BrepSolid,BrepSolidShell,BrepCurve,BrepCurve2,BrepSurface,SemioPoint2,SemioPoint3};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,Reconstruction},validate_sqlite_database_schema,SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding}};
use std::collections::{BTreeMap,BTreeSet};
fn number(n:usize)->Result<i64,String>{i64::try_from(n).map_err(|e|e.to_string())}
fn boolean(n:i64)->Result<bool,String>{match n{0=>Ok(false),1=>Ok(true),_=>Err("invalid BRep boolean".into())}}
fn identity<'a>(r:impl std::borrow::Borrow<SqliteRow<'a>>,n:usize)->Result<(),String>{let r=*r.borrow();if r.rowid<=0||r.integer(0)?!=r.rowid||r.values.len()!=n{Err("invalid BRep row identity or columns".into())}else{Ok(())}}
fn point3(r:SqliteRow<'_>,i:usize)->Result<SemioPoint3,String>{Ok(SemioPoint3{x:r.real(i)?,y:r.real(i+1)?,z:r.real(i+2)?})}
fn point2(r:SqliteRow<'_>,i:usize)->Result<SemioPoint2,String>{Ok(SemioPoint2{x:r.real(i)?,y:r.real(i+1)?})}
fn put3(c:&mut[Cell<'_>],i:usize,p:SemioPoint3){c[i]=Cell::Real(p.x);c[i+1]=Cell::Real(p.y);c[i+2]=Cell::Real(p.z);}
fn put2(c:&mut[Cell<'_>],i:usize,p:SemioPoint2){c[i]=Cell::Real(p.x);c[i+1]=Cell::Real(p.y);}
fn scalars(table:&str,id:i64,values:&[f64],p:&mut Projection<'_,'_>)->Result<(),String>{for(ordinal,v)in values.iter().enumerate(){p.insert_float(table,&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(*v)])?;}Ok(())}
fn points3(table:&str,id:i64,values:&[SemioPoint3],p:&mut Projection<'_,'_>)->Result<(),String>{for(ordinal,v)in values.iter().enumerate(){p.insert_float(table,&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(v.x),Cell::Real(v.y),Cell::Real(v.z)])?;}Ok(())}
fn project_curve3(curve:&BrepCurve,p:&mut Projection<'_,'_>)->Result<i64,String>{let mut c=[Cell::Null;17];match curve{BrepCurve::Line{origin,direction}=>{c[0]=Cell::Text("line");put3(&mut c,1,*origin);put3(&mut c,4,*direction);},BrepCurve::Circle{center,axis,radius}=>{c[0]=Cell::Text("circle");put3(&mut c,7,*center);put3(&mut c,10,*axis);c[13]=Cell::Real(*radius);},BrepCurve::Ellipse{center,axis,radius_major,radius_minor}=>{c[0]=Cell::Text("ellipse");put3(&mut c,7,*center);put3(&mut c,10,*axis);c[14]=Cell::Real(*radius_major);c[15]=Cell::Real(*radius_minor);},BrepCurve::Nurbs{degree,..}=>{c[0]=Cell::Text("nurbs");c[16]=Cell::Integer(i64::from(*degree));}}let id=p.insert_float("semio_brep_curve3",&c)?;if let BrepCurve::Nurbs{control_points,weights,knots,..}=curve{points3("semio_brep_curve3_point",id,control_points,p)?;scalars("semio_brep_curve3_weight",id,weights,p)?;scalars("semio_brep_curve3_knot",id,knots,p)?;}Ok(id)}
fn project_curve2(curve:&BrepCurve2,p:&mut Projection<'_,'_>)->Result<i64,String>{let mut c=[Cell::Null;13];match curve{BrepCurve2::Line{origin,direction}=>{c[0]=Cell::Text("line");put2(&mut c,1,*origin);put2(&mut c,3,*direction);},BrepCurve2::Circle{center,radius}=>{c[0]=Cell::Text("circle");put2(&mut c,5,*center);c[9]=Cell::Real(*radius);},BrepCurve2::Ellipse{center,x_axis,radius_major,radius_minor}=>{c[0]=Cell::Text("ellipse");put2(&mut c,5,*center);put2(&mut c,7,*x_axis);c[10]=Cell::Real(*radius_major);c[11]=Cell::Real(*radius_minor);},BrepCurve2::Nurbs{degree,..}=>{c[0]=Cell::Text("nurbs");c[12]=Cell::Integer(i64::from(*degree));}}let id=p.insert_float("semio_brep_curve2",&c)?;if let BrepCurve2::Nurbs{control_points,weights,knots,..}=curve{for(ordinal,v)in control_points.iter().enumerate(){p.insert_float("semio_brep_curve2_point",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(v.x),Cell::Real(v.y)])?;}scalars("semio_brep_curve2_weight",id,weights,p)?;scalars("semio_brep_curve2_knot",id,knots,p)?;}Ok(id)}
fn project_surface(surface:&BrepSurface,p:&mut Projection<'_,'_>)->Result<i64,String>{let mut c=[Cell::Null;21];match surface{BrepSurface::Plane{origin,normal}=>{c[0]=Cell::Text("plane");put3(&mut c,1,*origin);put3(&mut c,10,*normal);},BrepSurface::Cylinder{origin,axis,radius}=>{c[0]=Cell::Text("cylinder");put3(&mut c,1,*origin);put3(&mut c,4,*axis);c[13]=Cell::Real(*radius);},BrepSurface::Cone{origin,axis,radius,half_angle}=>{c[0]=Cell::Text("cone");put3(&mut c,1,*origin);put3(&mut c,4,*axis);c[13]=Cell::Real(*radius);c[14]=Cell::Real(*half_angle);},BrepSurface::Sphere{center,radius}=>{c[0]=Cell::Text("sphere");put3(&mut c,7,*center);c[13]=Cell::Real(*radius);},BrepSurface::Torus{center,axis,major_radius,minor_radius}=>{c[0]=Cell::Text("torus");put3(&mut c,7,*center);put3(&mut c,4,*axis);c[15]=Cell::Real(*major_radius);c[16]=Cell::Real(*minor_radius);},BrepSurface::Nurbs{u_count,v_count,degree_u,degree_v,..}=>{c[0]=Cell::Text("nurbs");c[17]=Cell::Integer(i64::from(*u_count));c[18]=Cell::Integer(i64::from(*v_count));c[19]=Cell::Integer(i64::from(*degree_u));c[20]=Cell::Integer(i64::from(*degree_v));}}let id=p.insert_float("semio_brep_surface",&c)?;if let BrepSurface::Nurbs{control_points,weights,knots_u,knots_v,..}=surface{points3("semio_brep_surface_point",id,control_points,p)?;scalars("semio_brep_surface_weight",id,weights,p)?;scalars("semio_brep_surface_knot_u",id,knots_u,p)?;scalars("semio_brep_surface_knot_v",id,knots_v,p)?;}Ok(id)}
fn ids<'a>(names:impl Iterator<Item=&'a str>,p:&mut Projection<'_,'_>)->Result<BTreeMap<&'a str,i64>,String>{let mut result=BTreeMap::new();for(ordinal,name)in names.enumerate(){p.check_rows(ordinal+1)?;if result.insert(name,number(ordinal+1)?).is_some(){return Err("duplicate BRep native entity identity".into());}if ordinal%256==0{p.checkpoint()?;}}Ok(result)}
fn fk(names:&BTreeMap<&str,i64>,id:&str)->Result<i64,String>{names.get(id).copied().ok_or_else(||"dangling BRep topology reference".into())}
fn ring(rows:&BTreeMap<i64,SqliteRow<'_>>,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{for(n,row)in rows.values().enumerate(){let next=rows.get(&row.integer(10)?).ok_or("dangling next coedge")?;let prev=rows.get(&row.integer(11)?).ok_or("dangling previous coedge")?;if next.integer(11)?!=row.rowid||prev.integer(10)?!=row.rowid||next.integer(9)?!=row.integer(9)?||prev.integer(9)?!=row.integer(9)?{return Err("nonreciprocal or cross-loop BRep coedge ring".into());}if n%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,n,0)?;}}Ok(())}
fn details<'a>(db:&'a SqliteDatabase,name:&str,n:usize,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,SqliteRow<'a>>,String>{let mut result=BTreeMap::new();for(count,row)in float_rows(db,name,c)?.into_iter().enumerate(){identity(row,n)?;if result.insert(row.rowid,row).is_some(){return Err("duplicate BRep row identity".into());}if count%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn groups<'a>(db:&'a SqliteDatabase,name:&str,n:usize,parents:&BTreeMap<i64,SqliteRow<'_>>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<SqliteRow<'a>>>,String>{let mut result=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();for row in details(db,name,n,c)?.into_values(){if !parents.contains_key(&row.integer(1)?){return Err("dangling BRep sequence owner".into());}row.integer(2)?;result.entry(row.integer(1)?).or_default().push(row);}for rows in result.values_mut(){rows.sort_by_key(|r|r.integer(2).unwrap_or(-1));for(ordinal,r)in rows.iter().enumerate(){if r.integer(2)?!=number(ordinal)?{return Err("BRep sequence ordinals must be contiguous".into());}}}Ok(result)}
fn shape(row:SqliteRow<'_>,active:&[usize])->Result<(),String>{for i in 2..row.values.len(){if !active.contains(&i)&&!row.is_null(i)?{return Err("contradictory BRep analytic geometry fields".into());}}Ok(())}
fn real_sequence(rows:Vec<SqliteRow<'_>>)->Result<Vec<f64>,String>{rows.into_iter().map(|r|r.real(3)).collect()}
fn curves3(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,BrepCurve>,String>{let rows=details(db,"semio_brep_curve3",18,c)?;let mut points=groups(db,"semio_brep_curve3_point",6,&rows,c)?;let mut weights=groups(db,"semio_brep_curve3_weight",4,&rows,c)?;let mut knots=groups(db,"semio_brep_curve3_knot",4,&rows,c)?;let mut result=BTreeMap::new();for row in rows.into_values(){let id=row.rowid;let curve=match row.text(1)?{
"line"=>{shape(row,&[2,3,4,5,6,7])?;BrepCurve::Line{origin:point3(row,2)?,direction:point3(row,5)?}},"circle"=>{shape(row,&[8,9,10,11,12,13,14])?;BrepCurve::Circle{center:point3(row,8)?,axis:point3(row,11)?,radius:row.real(14)?}},"ellipse"=>{shape(row,&[8,9,10,11,12,13,15,16])?;BrepCurve::Ellipse{center:point3(row,8)?,axis:point3(row,11)?,radius_major:row.real(15)?,radius_minor:row.real(16)?}},"nurbs"=>{shape(row,&[17])?;BrepCurve::Nurbs{control_points:points.remove(&id).unwrap_or_default().into_iter().map(|r|point3(r,3)).collect::<Result<_,_>>()?,weights:real_sequence(weights.remove(&id).unwrap_or_default())?,degree:u32::try_from(row.integer(17)?).map_err(|e|e.to_string())?,knots:real_sequence(knots.remove(&id).unwrap_or_default())?}},_=>return Err("unknown BRep 3D curve kind".into())};result.insert(id,curve);c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,result.len(),0)?;}if !points.is_empty()||!weights.is_empty()||!knots.is_empty(){return Err("parameter sequences on non-NURBS 3D curves".into());}Ok(result)}
fn curves2(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,BrepCurve2>,String>{let rows=details(db,"semio_brep_curve2",14,c)?;let mut points=groups(db,"semio_brep_curve2_point",5,&rows,c)?;let mut weights=groups(db,"semio_brep_curve2_weight",4,&rows,c)?;let mut knots=groups(db,"semio_brep_curve2_knot",4,&rows,c)?;let mut result=BTreeMap::new();for row in rows.into_values(){let id=row.rowid;let curve=match row.text(1)?{
"line"=>{shape(row,&[2,3,4,5])?;BrepCurve2::Line{origin:point2(row,2)?,direction:point2(row,4)?}},"circle"=>{shape(row,&[6,7,10])?;BrepCurve2::Circle{center:point2(row,6)?,radius:row.real(10)?}},"ellipse"=>{shape(row,&[6,7,8,9,11,12])?;BrepCurve2::Ellipse{center:point2(row,6)?,x_axis:point2(row,8)?,radius_major:row.real(11)?,radius_minor:row.real(12)?}},"nurbs"=>{shape(row,&[13])?;BrepCurve2::Nurbs{control_points:points.remove(&id).unwrap_or_default().into_iter().map(|r|point2(r,3)).collect::<Result<_,_>>()?,weights:real_sequence(weights.remove(&id).unwrap_or_default())?,degree:u32::try_from(row.integer(13)?).map_err(|e|e.to_string())?,knots:real_sequence(knots.remove(&id).unwrap_or_default())?}},_=>return Err("unknown BRep p-curve kind".into())};result.insert(id,curve);c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,result.len(),0)?;}if !points.is_empty()||!weights.is_empty()||!knots.is_empty(){return Err("parameter sequences on non-NURBS p-curves".into());}Ok(result)}
fn surfaces(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,BrepSurface>,String>{let rows=details(db,"semio_brep_surface",22,c)?;let mut points=groups(db,"semio_brep_surface_point",6,&rows,c)?;let mut weights=groups(db,"semio_brep_surface_weight",4,&rows,c)?;let mut knots_u=groups(db,"semio_brep_surface_knot_u",4,&rows,c)?;let mut knots_v=groups(db,"semio_brep_surface_knot_v",4,&rows,c)?;let mut result=BTreeMap::new();for row in rows.into_values(){let id=row.rowid;let surface=match row.text(1)?{
"plane"=>{shape(row,&[2,3,4,11,12,13])?;BrepSurface::Plane{origin:point3(row,2)?,normal:point3(row,11)?}},"cylinder"=>{shape(row,&[2,3,4,5,6,7,14])?;BrepSurface::Cylinder{origin:point3(row,2)?,axis:point3(row,5)?,radius:row.real(14)?}},"cone"=>{shape(row,&[2,3,4,5,6,7,14,15])?;BrepSurface::Cone{origin:point3(row,2)?,axis:point3(row,5)?,radius:row.real(14)?,half_angle:row.real(15)?}},"sphere"=>{shape(row,&[8,9,10,14])?;BrepSurface::Sphere{center:point3(row,8)?,radius:row.real(14)?}},"torus"=>{shape(row,&[5,6,7,8,9,10,16,17])?;BrepSurface::Torus{center:point3(row,8)?,axis:point3(row,5)?,major_radius:row.real(16)?,minor_radius:row.real(17)?}},"nurbs"=>{shape(row,&[18,19,20,21])?;BrepSurface::Nurbs{control_points:points.remove(&id).unwrap_or_default().into_iter().map(|r|point3(r,3)).collect::<Result<_,_>>()?,weights:real_sequence(weights.remove(&id).unwrap_or_default())?,u_count:u32::try_from(row.integer(18)?).map_err(|e|e.to_string())?,v_count:u32::try_from(row.integer(19)?).map_err(|e|e.to_string())?,degree_u:u32::try_from(row.integer(20)?).map_err(|e|e.to_string())?,degree_v:u32::try_from(row.integer(21)?).map_err(|e|e.to_string())?,knots_u:real_sequence(knots_u.remove(&id).unwrap_or_default())?,knots_v:real_sequence(knots_v.remove(&id).unwrap_or_default())?}},_=>return Err("unknown BRep surface kind".into())};result.insert(id,surface);c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,result.len(),0)?;}if !points.is_empty()||!weights.is_empty()||!knots_u.is_empty()||!knots_v.is_empty(){return Err("parameter sequences on non-NURBS surfaces".into());}Ok(result)}
fn native_names<'a>(rows:&[SqliteRow<'a>],columns:usize)->Result<BTreeMap<i64,&'a str>,String>{let mut names=BTreeSet::new();let mut result=BTreeMap::new();for row in rows{identity(row,columns)?;if row.integer(1)?!=1||!names.insert(row.text(3)?)||result.insert(row.rowid,row.text(3)?).is_some(){return Err("invalid BRep native identity or document owner".into());}}Ok(result)}
fn named(names:&BTreeMap<i64,&str>,id:i64,r:&mut Reconstruction<'_,'_>)->Result<String,String>{r.text(names.get(&id).ok_or("dangling BRep native reference")?)}
impl ArtifactSqliteSnapshot for SemioBrepSnapshot{
fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,String>{super::native_encoding::encode(self,encoding,control)}
fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{super::native_decoding::decode(payload,control)}
fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=Bound::new("",control)?;self.native_fields(&mut b)?;b.finish()}

fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;
if dialect.artifact_kind!="s.stdio.semio"||dialect.standard!="v1"||(dialect.subset!="*"&&dialect.subset!="brep"){return Err(String::from("Semio owned snapshot dialect differs from its dedicated semantic subset").into());}
let row=database.table("semio_brep_document")?.single_row()?;
if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(String::from("Semio owned document identity differs from projected semantic fields").into());}
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}

const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;p.insert_key_float("semio_brep_document",1,&[Cell::Text(&self.schema),Cell::Text(&self.next_label.to_string())])?;let vertices=ids(self.vertices.iter().map(|v|v.id.as_str()),&mut p)?;let edges=ids(self.edges.iter().map(|v|v.id.as_str()),&mut p)?;let loops=ids(self.loops.iter().map(|v|v.id.as_str()),&mut p)?;let faces=ids(self.faces.iter().map(|v|v.id.as_str()),&mut p)?;let shells=ids(self.shells.iter().map(|v|v.id.as_str()),&mut p)?;let solids=ids(self.solids.iter().map(|v|v.id.as_str()),&mut p)?;let coedges=ids(self.coedges.iter().map(|v|v.id.as_str()),&mut p)?;
for(ordinal,v)in self.vertices.iter().enumerate(){p.insert_key_float("semio_brep_vertex",vertices[v.id.as_str()],&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&v.id),Cell::Real(v.point.x),Cell::Real(v.point.y),Cell::Real(v.point.z),Cell::Real(v.tol)])?;}
for(ordinal,e)in self.edges.iter().enumerate(){let curve=project_curve3(&e.curve,&mut p)?;p.insert_key_float("semio_brep_edge",edges[e.id.as_str()],&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&e.id),Cell::Integer(fk(&vertices,&e.start_vertex)?),Cell::Integer(fk(&vertices,&e.end_vertex)?),Cell::Integer(curve),Cell::Real(e.tol)])?;}
for(ordinal,l)in self.loops.iter().enumerate(){let id=loops[l.id.as_str()];p.insert_key_float("semio_brep_loop",id,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&l.id)])?;for(ordinal,e)in l.edges.iter().enumerate(){p.insert_float("semio_brep_loop_edge",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Integer(fk(&edges,&e.edge)?),Cell::Integer(i64::from(e.orientation))])?;}}
for(ordinal,f)in self.faces.iter().enumerate(){let id=faces[f.id.as_str()];let surface=project_surface(&f.surface,&mut p)?;p.insert_key_float("semio_brep_face",id,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&f.id),Cell::Integer(fk(&loops,&f.outer_loop)?),Cell::Integer(surface),Cell::Integer(i64::from(f.orientation)),Cell::Real(f.tol)])?;for(ordinal,l)in f.inner_loops.iter().enumerate(){p.insert_float("semio_brep_inner_loop",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Integer(fk(&loops,l)?)])?;}}
for(ordinal,s)in self.shells.iter().enumerate(){let id=shells[s.id.as_str()];p.insert_key_float("semio_brep_shell",id,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&s.id)])?;for(ordinal,f)in s.faces.iter().enumerate(){p.insert_float("semio_brep_shell_face",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Integer(fk(&faces,&f.face)?),Cell::Integer(i64::from(f.orientation))])?;}}
for(ordinal,s)in self.solids.iter().enumerate(){let id=solids[s.id.as_str()];p.insert_key_float("semio_brep_solid",id,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&s.id)])?;for(ordinal,l)in s.shells.iter().enumerate(){p.insert_float("semio_brep_solid_shell",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Integer(fk(&shells,&l.shell)?),Cell::Integer(i64::from(l.is_void))])?;}}
for(ordinal,e)in self.coedges.iter().enumerate(){let curve=e.pcurve.as_ref().map(|v|project_curve2(v,&mut p)).transpose()?;p.insert_key_float("semio_brep_coedge",coedges[e.id.as_str()],&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&e.id),Cell::Integer(fk(&edges,&e.edge)?),Cell::Integer(i64::from(e.forward)),curve.map(Cell::Integer).unwrap_or(Cell::Null),Cell::Real(e.prange.0),Cell::Real(e.prange.1),Cell::Integer(fk(&loops,&e.loop_id)?),Cell::Integer(fk(&coedges,&e.next)?),Cell::Integer(fk(&coedges,&e.prev)?)])?;}let db=p.finish()?;let rings=details(&db,"semio_brep_coedge",12,c)?;ring(&rings,c)?;Ok(db)}
fn from_sqlite_database(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String> { Self::reconstruct_sqlite_database(db, c, Self::SQLITE_SCHEMA) }
}

impl SemioBrepSnapshot {
    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,String> {
c.check_database(db,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(db,declared_schema,c.limits()).map_err(|e|e.to_string())?;let doc=single_float_row(db,"semio_brep_document")?;identity(doc,3)?;if doc.rowid!=1{return Err("invalid BRep document identity".into());}let next_label=doc.text(2)?.parse::<u64>().map_err(|e|e.to_string())?;if next_label.to_string()!=doc.text(2)?{return Err("noncanonical BRep unsigned label".into());}
let vertex_rows=ordered_float_rows(db,"semio_brep_vertex",2,c)?;let edge_rows=ordered_float_rows(db,"semio_brep_edge",2,c)?;let loop_rows=ordered_float_rows(db,"semio_brep_loop",2,c)?;let face_rows=ordered_float_rows(db,"semio_brep_face",2,c)?;let shell_rows=ordered_float_rows(db,"semio_brep_shell",2,c)?;let solid_rows=ordered_float_rows(db,"semio_brep_solid",2,c)?;let coedge_rows=ordered_float_rows(db,"semio_brep_coedge",2,c)?;
let vertex_names=native_names(&vertex_rows,8)?;let edge_names=native_names(&edge_rows,8)?;let loop_names=native_names(&loop_rows,4)?;let face_names=native_names(&face_rows,8)?;let shell_names=native_names(&shell_rows,4)?;native_names(&solid_rows,4)?;let coedge_names=native_names(&coedge_rows,12)?;
let raw_loops=details(db,"semio_brep_loop",4,c)?;let raw_faces=details(db,"semio_brep_face",8,c)?;let raw_shells=details(db,"semio_brep_shell",4,c)?;let raw_solids=details(db,"semio_brep_solid",4,c)?;let raw_coedges=details(db,"semio_brep_coedge",12,c)?;ring(&raw_coedges,c)?;let mut loop_edges=groups(db,"semio_brep_loop_edge",5,&raw_loops,c)?;let mut inner_loops=groups(db,"semio_brep_inner_loop",4,&raw_faces,c)?;let mut shell_faces=groups(db,"semio_brep_shell_face",5,&raw_shells,c)?;let mut solid_shells=groups(db,"semio_brep_solid_shell",5,&raw_solids,c)?;let mut curves3=curves3(db,c)?;let mut curves2=curves2(db,c)?;let mut surfaces=surfaces(db,c)?;let mut r=Reconstruction::new(c)?;
let mut vertices=Vec::new();for row in vertex_rows{vertices.push(BrepVertex{id:r.text(row.text(3)?)?,point:point3(row,4)?,tol:row.real(7)?});r.checkpoint()?;}
let mut edges=Vec::new();for row in edge_rows{edges.push(BrepEdge{id:r.text(row.text(3)?)?,start_vertex:named(&vertex_names,row.integer(4)?,&mut r)?,end_vertex:named(&vertex_names,row.integer(5)?,&mut r)?,curve:curves3.remove(&row.integer(6)?).ok_or("missing multiply owned or dangling edge curve")?,tol:row.real(7)?});r.checkpoint()?;}
let mut loops=Vec::new();for row in loop_rows{let mut native=Vec::new();for edge in loop_edges.remove(&row.rowid).unwrap_or_default(){native.push(BrepLoopEdge{edge:named(&edge_names,edge.integer(3)?,&mut r)?,orientation:boolean(edge.integer(4)?)?});}loops.push(BrepLoop{id:r.text(row.text(3)?)?,edges:native});r.checkpoint()?;}
let mut faces=Vec::new();for row in face_rows{let mut native=Vec::new();for l in inner_loops.remove(&row.rowid).unwrap_or_default(){native.push(named(&loop_names,l.integer(3)?,&mut r)?);}faces.push(BrepFace{id:r.text(row.text(3)?)?,outer_loop:named(&loop_names,row.integer(4)?,&mut r)?,inner_loops:native,surface:surfaces.remove(&row.integer(5)?).ok_or("missing multiply owned or dangling face surface")?,orientation:boolean(row.integer(6)?)?,tol:row.real(7)?});r.checkpoint()?;}
let mut shells=Vec::new();for row in shell_rows{let mut native=Vec::new();for f in shell_faces.remove(&row.rowid).unwrap_or_default(){native.push(BrepShellFace{face:named(&face_names,f.integer(3)?,&mut r)?,orientation:boolean(f.integer(4)?)?});}shells.push(BrepShell{id:r.text(row.text(3)?)?,faces:native});r.checkpoint()?;}
let mut solids=Vec::new();for row in solid_rows{let mut native=Vec::new();for s in solid_shells.remove(&row.rowid).unwrap_or_default(){native.push(BrepSolidShell{shell:named(&shell_names,s.integer(3)?,&mut r)?,is_void:boolean(s.integer(4)?)?});}solids.push(BrepSolid{id:r.text(row.text(3)?)?,shells:native});r.checkpoint()?;}
let mut coedges=Vec::new();for row in coedge_rows{let pcurve=if row.is_null(6)?{None}else{Some(curves2.remove(&row.integer(6)?).ok_or("missing multiply owned or dangling p-curve")?)};coedges.push(BrepCoedge{id:r.text(row.text(3)?)?,edge:named(&edge_names,row.integer(4)?,&mut r)?,forward:boolean(row.integer(5)?)?,pcurve,prange:(row.real(7)?,row.real(8)?),loop_id:named(&loop_names,row.integer(9)?,&mut r)?,next:named(&coedge_names,row.integer(10)?,&mut r)?,prev:named(&coedge_names,row.integer(11)?,&mut r)?});r.checkpoint()?;}
if !curves3.is_empty()||!curves2.is_empty()||!surfaces.is_empty()||!loop_edges.is_empty()||!inner_loops.is_empty()||!shell_faces.is_empty()||!solid_shells.is_empty(){return Err("orphan BRep owned geometry or relationship".into());}let value=Self{schema:r.text(doc.text(1)?)?,vertices,edges,loops,faces,shells,solids,coedges,next_label};r.checkpoint()?;Ok(value)
    }
}

